 for name in names:
  m=re.search(r'^typedef (?:struct|enum) _?'+re.escape(name)+r'\s*\{[\s\S]*?^} '+re.escape(name)+r';',s,re.M)
  if not m:m=re.search(r'^(?:VKAPI_ATTR|ZE_APIEXPORT)[\s\S]*?\b'+re.escape(name)+r'\([\s\S]*?\);',s,re.M)
